NEW = {'deps/CodeGen/src/Jitter_CodeGen_Wasm_RegisterReuse.h': "// Private ordinary-register first-read reuse prototype. Included by Wasm.cpp only.\n// Constants are fixed proof bounds, not tuned to any guest workload.\nvoid CCodeGen_Wasm::SetRelativeReadReuseRegions(const RelativeReadReuseRegions& regions)\n{\n m_reuseRegions = regions;\n}\n\nuint32 CCodeGen_Wasm::RelativeReadWidth(SYM_TYPE type)\n{\n switch(type)\n {\n case SYM_RELATIVE: case SYM_FP_RELATIVE32: return 4;\n case SYM_RELATIVE64: return 8;\n case SYM_RELATIVE128: return 16;\n default: return 0;\n }\n}\n\nbool CCodeGen_Wasm::ReusePureOp(OPERATION op)\n{\n // Explicit reviewed emitter family. All other and future operations are barriers.\n switch(op)\n {\n case OP_MOV: case OP_ADD: case OP_SUB: case OP_CMP: case OP_SELECT:\n case OP_AND: case OP_OR: case OP_XOR: case OP_NOT:\n case OP_SRA: case OP_SRL: case OP_SLL: case OP_LZC:\n case OP_ADD64: case OP_SUB64: case OP_AND64: case OP_CMP64:\n case OP_MERGETO64: case OP_EXTLOW64: case OP_EXTHIGH64:\n case OP_SRA64: case OP_SRL64: case OP_SLL64:\n case OP_FP_ADD_S: case OP_FP_SUB_S: case OP_FP_MUL_S: case OP_FP_DIV_S:\n case OP_FP_SQRT_S: case OP_FP_RSQRT_S: case OP_FP_RCPL_S:\n case OP_FP_ABS_S: case OP_FP_NEG_S: case OP_FP_MAX_S: case OP_FP_MIN_S:\n case OP_FP_CMP_S: case OP_FP_CLAMP_S: case OP_FP_LDCST:\n case OP_MD_ADD_B: case OP_MD_ADD_H: case OP_MD_ADD_W:\n case OP_MD_SUB_B: case OP_MD_SUB_H: case OP_MD_SUB_W:\n case OP_MD_AND: case OP_MD_OR: case OP_MD_XOR: case OP_MD_NOT:\n case OP_MD_ADD_S: case OP_MD_SUB_S: case OP_MD_MUL_S: case OP_MD_DIV_S:\n case OP_MD_ABS_S: case OP_MD_NEG_S: case OP_MD_MIN_S: case OP_MD_MAX_S:\n case OP_MD_CMPLT_S: case OP_MD_CMPGT_S: case OP_MD_CLAMP_S:\n case OP_MD_MOV_MASKED:\n  return true;\n default: return false;\n }\n}\n\nvoid CCodeGen_Wasm::MarkRelativeReadReuse(StatementList& statements)\n{\n // Mark before coalescing: temporary identities here still describe their\n // original definitions. A whole cone statement becomes a barrier, including\n // definitions with additional ordinary consumers. This feature mutates no operands.\n for(auto& s : statements)\n {\n  s.relativeReadReuse = !m_reuseRegions.empty() && ReusePureOp(s.op);\n  s.VisitOperands([&](const SymbolRefPtr& r, bool) {\n   const auto type = r->GetSymbol()->m_type;\n   if(!RelativeReadWidth(type) && type != SYM_CONSTANT && type != SYM_CONSTANT64 &&\n      type != SYM_TEMPORARY && type != SYM_TEMPORARY64 &&\n      type != SYM_TEMPORARY128 && type != SYM_FP_TEMPORARY32)\n    s.relativeReadReuse = false;\n  });\n }\n std::set<CSymbol*> needed;\n for(auto it = statements.rbegin(); it != statements.rend(); ++it)\n {\n  auto& s = *it;\n  auto dst = s.dst ? s.dst->GetSymbol().get() : nullptr;\n  if(s.op != OP_MD_MAKESZ && (!dst || !needed.count(dst))) continue;\n  s.relativeReadReuse = false;\n  if(dst) needed.erase(dst);\n  s.VisitSources([&](const SymbolRefPtr& r, bool) {\n   auto src = r->GetSymbol().get();\n   if(src->IsTemporary()) needed.insert(src);\n  });\n }\n}\n\nbool CCodeGen_Wasm::IsReuseSource(CSymbol* symbol) const\n{\n const uint32 width = RelativeReadWidth(symbol->m_type);\n if(!width) return false;\n const uint32 offset = symbol->m_valueLow;\n for(const auto& region : m_reuseRegions)\n  if(offset >= region.first && width <= region.second &&\n     offset - region.first <= region.second - width) return true;\n return false;\n}\n\nbool CCodeGen_Wasm::ReuseWriteOverlaps(const STATEMENT& s, CSymbol* read) const\n{\n if(!s.dst) return false;\n auto dst = s.dst->GetSymbol().get();\n uint32 width = RelativeReadWidth(dst->m_type);\n if(!width) return false; // Marking rejects every unknown relative/reference kind.\n // uint64 endpoints avoid overflow; masked writes invalidate all 16 bytes.\n return uint64(dst->m_valueLow) < uint64(read->m_valueLow) + RelativeReadWidth(read->m_type) &&\n        uint64(read->m_valueLow) < uint64(dst->m_valueLow) + width;\n}\n\nvoid CCodeGen_Wasm::PrepareRelativeReadReuse(const StatementList& statements)\n{\n m_reuseLocals.clear(); m_reuseStatements.clear(); m_reuseStatement = 0;\n m_reuseEnabledHere = false;\n for(const auto& s : statements) m_reuseStatements.push_back(&s);\n for(uint32 i = 0; i < m_reuseStatements.size(); i++)\n {\n  const auto& s = *m_reuseStatements[i];\n  if(!s.relativeReadReuse) continue;\n  s.VisitSources([&](const SymbolRefPtr& r, bool) {\n   auto read = r->GetSymbol().get();\n   if(!IsReuseSource(read)) return;\n   const auto key = std::make_pair(read->m_type, read->m_valueLow);\n   if(m_reuseLocals.count(key) || m_reuseLocals.size() >= 8) return;\n   if(ReuseWriteOverlaps(s, read)) return;\n   // A cache is allocated only for a distinct later statement's matching read.\n   for(uint32 j = i + 1; j < m_reuseStatements.size() && j - i <= 32; j++)\n   {\n    const auto& next = *m_reuseStatements[j];\n    if(!next.relativeReadReuse) break;\n    bool match = false;\n    next.VisitSources([&](const SymbolRefPtr& nextRef, bool) {\n     auto other = nextRef->GetSymbol().get();\n     match |= other->m_type == read->m_type && other->m_valueLow == read->m_valueLow;\n    });\n    if(match)\n    {\n     uint32 location = 0;\n     switch(read->m_type)\n     {\n     case SYM_RELATIVE: location = m_localI32Count++; break;\n     case SYM_RELATIVE64: location = m_localI64Count++; break;\n     case SYM_FP_RELATIVE32: location = m_localF32Count++; break;\n     case SYM_RELATIVE128: location = m_localV128Count++; break;\n     default: assert(false);\n     }\n     m_reuseLocals.emplace(key, ReuseLocal{location, 0, false});\n     break;\n    }\n    if(ReuseWriteOverlaps(next, read)) break;\n   }\n  });\n }\n}\n\nuint32 CCodeGen_Wasm::ReuseLocalIndex(SYM_TYPE type, uint32 location) const\n{\n switch(type)\n {\n case SYM_RELATIVE: return location + 1;\n case SYM_RELATIVE64: return location + m_localI32Count + 1;\n case SYM_FP_RELATIVE32: return location + m_localI32Count + m_localI64Count + 1;\n case SYM_RELATIVE128: return location + m_localI32Count + m_localI64Count + m_localF32Count + 1;\n default: assert(false); return 0;\n }\n}\n\nvoid CCodeGen_Wasm::BeginReuseStatement(const STATEMENT& s)\n{\n m_reuseEnabledHere = s.relativeReadReuse;\n for(auto& entry : m_reuseLocals)\n  if(!m_reuseEnabledHere || m_reuseStatement - entry.second.firstStatement > 32)\n   entry.second.valid = false;\n}\n\nvoid CCodeGen_Wasm::EndReuseStatement(const STATEMENT& s)\n{\n for(auto& entry : m_reuseLocals)\n {\n  CSymbol read(entry.first.first, entry.first.second, 0);\n  if(!m_reuseEnabledHere || ReuseWriteOverlaps(s, &read)) entry.second.valid = false;\n }\n m_reuseEnabledHere = false;\n m_reuseStatement++;\n}\n\nbool CCodeGen_Wasm::PushReusedRelative(CSymbol* symbol)\n{\n if(!m_reuseEnabledHere) return false;\n const auto it = m_reuseLocals.find(std::make_pair(symbol->m_type, symbol->m_valueLow));\n if(it == m_reuseLocals.end() || !it->second.valid) return false;\n m_functionStream.Write8(Wasm::INST_LOCAL_GET);\n CWasmModuleBuilder::WriteULeb128(m_functionStream, ReuseLocalIndex(symbol->m_type, it->second.location));\n return true;\n}\n\nvoid CCodeGen_Wasm::CaptureRelativeRead(CSymbol* symbol)\n{\n if(!m_reuseEnabledHere) return;\n const auto it = m_reuseLocals.find(std::make_pair(symbol->m_type, symbol->m_valueLow));\n if(it == m_reuseLocals.end()) return;\n // Reserve no value unless this actual read has a matching future read before\n // any barrier/write. This also bounds liveness after an invalidation/re-entry.\n const auto& here = *m_reuseStatements[m_reuseStatement];\n if(ReuseWriteOverlaps(here, symbol)) return;\n for(uint32 j = m_reuseStatement + 1; j < m_reuseStatements.size() && j - m_reuseStatement <= 32; j++)\n {\n  const auto& next = *m_reuseStatements[j];\n  if(!next.relativeReadReuse) return;\n  bool match = false;\n  next.VisitSources([&](const SymbolRefPtr& r, bool) {\n   auto other = r->GetSymbol().get();\n   match |= other->m_type == symbol->m_type && other->m_valueLow == symbol->m_valueLow;\n  });\n  if(match)\n  {\n   // This is immediately AFTER the original typed load and leaves its value on\n   // the Wasm operand stack. No earlier operand/trap/store/call has moved.\n   m_functionStream.Write8(0x22); // WebAssembly local.tee (not named by this older WasmDefs).\n   CWasmModuleBuilder::WriteULeb128(m_functionStream, ReuseLocalIndex(symbol->m_type, it->second.location));\n   it->second.valid = true; it->second.firstStatement = m_reuseStatement;\n   return;\n  }\n  if(ReuseWriteOverlaps(next, symbol)) return;\n }\n}\n"}
def patch(root):
 root=Path(root);result={}
 for rel,digest in PINS.items():
  p=root/rel
  if hashlib.sha256(p.read_bytes()).hexdigest()!=digest:raise ValueError('Source drift: '+rel)
 for rel in NEW:
  if (root/rel).exists():raise ValueError('New source already exists: '+rel)
 for rel,edits in CHANGES.items():
  data=(root/rel).read_text()
  for old,new in reversed(edits):
   if data.count(old)!=1:raise ValueError('Ambiguous source anchor: '+rel)
   data=data.replace(old,new)
  result[rel]=data.encode()
 result.update({rel:data.encode() for rel,data in NEW.items()})
 for rel,data in result.items():
  if hashlib.sha256(data).hexdigest()!=PATCHED[rel]:raise ValueError('Patched hash mismatch: '+rel)
 for rel,data in result.items():
  p=root/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
 return PATCHED
if __name__=='__main__':patch(Path(sys.argv[1]))
